import sys

MOD = 10**9 + 7
GOOD_NUMBER = 2520

def count_good_ways(P, T):
    n = len(T)
    m = len(P)
    positions = []

    # Find all starting positions of P in T
    for i in range(n - m + 1):
        if T[i:i + m] == P:
            positions.append(i + 1)

    def is_good_number(num):
        return num % GOOD_NUMBER == 0

    def count_ways(positions):
        dp = [0] * (len(positions) + 1)
        dp[0] = 1

        for i in range(1, len(positions) + 1):
            dp[i] = dp[i - 1]
            for j in range(i):
                if is_good_number(positions[j - 1] * positions[i - 1]):
                    dp[i] = (dp[i] + dp[j]) % MOD

        return (sum(dp) - 1) % MOD

    return count_ways(positions)

input = sys.stdin.read().strip().split('\n')
P = input[0]
T = input[1]
print(count_good_ways(P, T))
